import os, sys, json, subprocess

PROJ = "storage/shared/agency_lab/repro_template/v2/template_project"
TOOLS = ".."  # parent of template_project

def run_cmd(cmd, cwd=None):
    p = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if p.returncode != 0:
        print("STDOUT:", p.stdout)
        print("STDERR:", p.stderr)
        raise SystemExit(p.returncode)
    s = p.stdout.strip()
    try:
        return json.loads(s)
    except Exception:
        return {"raw": s}

def main():
    cfg = "verify_config.json"
    pref = run_cmd([sys.executable, f"{TOOLS}/preflight_static.py", "--config", cfg], cwd=PROJ)
    run_out = run_cmd([sys.executable, f"{TOOLS}/run.py", "--config", cfg, "--cwd", "."], cwd=PROJ)
    ver_tol = run_cmd([sys.executable, f"{TOOLS}/verify.py", "--mode", "with-tolerance", "--config", cfg], cwd=PROJ)
    hash_out = run_cmd([sys.executable, f"{TOOLS}/hash_outputs.py", "--config", cfg, "--out", "verify_config.strict.json"], cwd=PROJ)
    ver_strict = run_cmd([sys.executable, f"{TOOLS}/verify.py", "--mode", "strict", "--config", "verify_config.strict.json"], cwd=PROJ)
    print(json.dumps({
        "preflight": pref,
        "run": run_out,
        "verify_tolerance": ver_tol,
        "hash_outputs": hash_out,
        "verify_strict": ver_strict
    }, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    main()

